INSERT 
	INTO BASIL_SEC_PRD.USERS (NAME, COMPANY_ID, EMAIL, PASSWORD, PASS_TOKEN, PASS_TOKEN_EXP, STATUS, CREATOR, MODIFIER)
	VALUES(#{name}, #{companyId}, #{email}, #{password}, #{token}, #{tokenExp}, #{status}, #{creator}, #{creator});

mapper.update:
UPDATE BASIL_SEC_PRD.USERS
	SET LAST_LOGIN_DATE = CURRENT_TIMESTAMP()
WHERE U_OID=#{id}

mapper.select:
SELECT count(*) FROM BASIL_SEC_PRD.USERS
NAME LIKE concat('%',#{name},'%')
AND COMPANY_ID=#{company}
AND STATUS=#{status}
AND EMAIL LIKE concat('%',#{email},'%')

		SELECT
			count(*)
		FROM
			BASIL_SEC_PRD.USERS


          		NAME LIKE concat('%',#{name},'%')


        		AND EMAIL LIKE concat('%',#{email},'%')


        		AND CREATED = #{registerTime}


        		AND LAST_LOGIN_DATE = #{lastLogin}


        		AND STATUS = #{status}

SELECT U_OID as id, NAME, COMPANY_ID, EMAIL, STATUS, (CASE WHEN STATUS = 1 THEN 'Active' WHEN STATUS = 2 THEN 'Disabled' WHEN STATUS = 3 THEN 'Inactive' END) statusStr FROM BASIL_SEC_PRD.USERS
NAME LIKE concat('%',#{name},'%')
AND COMPANY_ID=#{company}
AND STATUS=#{status}
AND EMAIL LIKE concat('%',#{email},'%')
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}

SELECT U_OID as id, NAME, EMAIL, CREATED, LAST_LOGIN_DATE, STATUS, (CASE WHEN STATUS = 1 THEN 'Active' WHEN STATUS = 2 THEN 'Disabled' WHEN STATUS = 3 THEN 'Inactive' END) statusStr FROM BASIL_SEC_PRD.USERS
